#!/usr/bin/env python3
"""Build the self-contained CMSMotive static-site HTML pages."""
from pathlib import Path

ROOT = Path(__file__).parent
IMG = "assets/images/"
ICON = "assets/icons/"


def arrow(up=False):
    file = "arrow-up-right.svg" if up else "arrow-right.svg"
    return f'<img src="{ICON}{file}" alt="" width="16" height="16">'


def btn(label, href, kind="primary", up=False):
    return f'<a class="btn btn-{kind}" href="{href}"><span class="btn-label">{label}</span><span class="btn-icon" aria-hidden="true">{arrow(up)}</span></a>'


def text_link(label, href):
    return f'<a class="text-link" href="{href}">{label}{arrow()}</a>'


def logo(location):
    return f'<a class="logo logo-{location}" href="index.html" aria-label="CMSMotive home"><img src="{IMG}logo.png" alt="CMSMotive" width="120" height="40"></a>'


def browser(image="nordform-architecture.webp", detail=False):
    image_class = "preview-image-index" if image == "hero-typo3-template-v1.webp" else "preview-image-nordform"
    return f'''<div class="browser {'detail-browser' if detail else ''}" aria-label="Nordform theme visual concept preview">
      <div class="browser-bar"><i></i><i></i><i></i><span class="browser-url">nordform.cmsmotive — visual preview</span></div>
      <div class="preview-site"><div class="preview-head"><span class="preview-word">NORDFORM<span class="preview-word-dot">.</span></span><span class="preview-menu"><span>Projects</span><span>Practice</span><span>Journal</span><span>Contact ↗</span></span></div>
      <div class="preview-image {image_class}"><div class="preview-overlay"><small>Architecture / Urban life / Form</small><strong>Ideas made<br>to last.</strong><span>Explore our work &nbsp; ↗</span></div></div></div>
    </div>'''


def product_card(name, category, image, description, badges, price, href, label="Theme concept"):
    chips = ''.join(f'<span class="badge {cls}">{text}</span>' for text, cls in badges)
    image_alts = {"nordform-architecture.webp": "Contemporary pale concrete architecture", "foundation-studio.webp": "Designer working in a bright architecture studio", "campus-library.webp": "Students outside a modern brick and glass campus library"}
    display_price = f'€{price}' if price else ('Free' if price == 0 else 'TBD')
    price_label = 'Preview price' if price else ('Planned price' if price == 0 else 'Roadmap price')
    return f'''<article class="product-card" data-product data-name="{name.lower()}" data-industry="{category.lower()}" data-price="{price if price is not None else -1}" data-version="13 14" data-reveal>
      <a class="product-visual" href="{href}" aria-label="Explore {name}"><img src="{IMG}{image}" width="1536" height="1024" loading="lazy" alt="{image_alts[image]}"><span class="visual-label">{label}</span></a>
      <div class="product-body"><span class="product-kicker">{category}</span><h3>{name}</h3><p>{description}</p><div class="badge-row">{chips}</div><div class="product-bottom"><span class="product-price"><small>{price_label}</small>{display_price}</span>{text_link('Explore theme',href)}</div></div>
    </article>'''


def section_title(kicker, title, description="", more=""):
    return f'''<div class="section-heading" data-reveal><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div>{'<div><p>'+description+'</p>'+more+'</div>' if description or more else ''}</div>'''


def page(filename, title, description, body, current="", image="nordform-architecture.webp", extra_head=""):
    navs = [("Themes", "themes.html"), ("Extensions", "extensions.html"), ("Headless", "headless.html"), ("Docs", "docs.html"), ("Pricing", "pricing.html"), ("Blog", "blog.html")]
    nav_html = ''.join(f'<a class="nav-link" href="{url}" {'aria-current="page"' if current==url else ''}>{label}</a>' for label,url in navs)
    mobile_html = ''.join(f'<a href="{url}" {'aria-current="page"' if current==url else ''}>{label}</a>' for label,url in navs)
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f8f5"><meta name="description" content="{description}"><title>{title} — CMSMotive</title>
<link rel="icon" type="image/png" href="assets/icons/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="assets/css/site.css"><meta property="og:title" content="{title} — CMSMotive"><meta property="og:description" content="{description}"><meta property="og:image" content="{IMG}{image}">{extra_head}</head>
<body><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="container header-inner">{logo('header')}<nav class="desktop-nav" aria-label="Primary navigation">{nav_html}</nav><div class="header-actions"><a class="nav-link" href="auth/login.html">Sign in</a>{btn('Explore themes','themes.html','primary')}<button class="menu-toggle" type="button" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span><span></span></button></div></div><nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation">{mobile_html}<a href="auth/login.html">Sign in</a>{btn('Explore themes','themes.html')}</nav></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand">{logo('footer')}<p>Thoughtful TYPO3 products for teams building real websites. Designed to make the next project feel less like starting over.</p></div><div class="footer-col"><div class="footer-label">Products</div><a href="themes.html">Themes</a><a href="theme-nordform.html">Nordform</a><a href="theme-foundation.html">Foundation</a><a href="theme-campus.html">Campus</a><a href="extensions.html">Extensions</a><a href="headless.html">Headless</a><a href="pricing.html">Licensing</a></div><div class="footer-col"><div class="footer-label">Resources</div><a href="docs.html">Documentation</a><a href="blog.html">Journal</a><a href="about.html">About</a><a href="contact.html">Contact</a></div><div class="footer-col"><div class="footer-label">Legal</div><a href="imprint.html">Imprint</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a><a href="cookies.html">Cookies</a></div></div><div class="footer-bottom"><p>© 2026 CMSMotive. Independent product concept. TYPO3 is a registered trademark of the TYPO3 Association; CMSMotive is not affiliated with or endorsed by the TYPO3 Association.</p><p>Built for the long run. &nbsp;↗</p></div></div></footer><script src="assets/js/site.js" defer></script></body></html>'''
    (ROOT / filename).write_text(html, encoding="utf-8")


def article_card(href, category, title, desc):
    return f'<article class="article-card" data-reveal><span class="micro">{category} &nbsp; / &nbsp; 2026</span><h3>{title}</h3><p>{desc}</p>{text_link("Read article",href)}</article>'


def faq():
    entries = [
        ("Can I buy Nordform today?", "Nordform is presented here as a visual and product concept. Request availability to receive verified specifications, a launch date and a purchase link when ready."),
        ("Will themes support TYPO3 13 and 14 LTS?", "That is the planned compatibility target. Exact supported versions will be listed on each released product and checked against its changelog."),
        ("Can agencies use a theme for multiple clients?", "The proposed Agency licence is intended for repeat client work. Final usage terms will be published before sales open."),
        ("Is the site affiliated with TYPO3?", "No. CMSMotive is an independent product brand. TYPO3 is a registered trademark of the TYPO3 Association."),
    ]
    items = ''.join(f'''<details class="faq-item" {'open' if i == 1 else ''}>
      <summary><span class="faq-number">{i:02d}</span><span class="faq-question">{q}</span><span class="faq-toggle" aria-hidden="true"></span></summary>
      <div class="faq-answer"><p>{a}</p></div>
    </details>''' for i, (q, a) in enumerate(entries, 1))
    return f'''<div class="faq-layout"><aside class="faq-info-card" data-reveal>
      <div class="faq-info-top"><img src="{IMG}logo.png" width="102" height="34" alt=""><span class="mono">CMSMOTIVE / HELP DESK</span></div>
      <div><span class="eyebrow light">Still have questions?</span><h3>Good decisions start with clear answers.</h3><p>Tell us about your TYPO3 version, project scope and team. We can help you find the right starting point.</p></div>
      <div class="faq-info-bottom"><span>01 &nbsp; Product fit</span><span>02 &nbsp; Licensing</span><span>03 &nbsp; Technical details</span></div>
      {btn('Ask a question','contact.html','lime')}
    </aside><div class="faq-list" data-reveal="delay">{items}</div></div>'''


